# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import (
    round_labels,
    round_span,
    snap
)


class SnapTests(unittest.TestCase):
    def test_nearest(self):
        self.assertEqual(snap(62, 15), 60)
        self.assertEqual(snap(68, 15), 75)

    def test_halves_go_up(self):
        self.assertEqual(snap(4, 10), 0)
        self.assertEqual(snap(5, 10), 10)
        self.assertEqual(snap(3, 6), 6)


class LabelTests(unittest.TestCase):
    def test_example_label(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 14)]
        result = round_labels(spans, 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span(self):
        spans = [Span(481, 600), Span(661, 720)]
        self.assertEqual(
            round_labels(spans, 30),
            ["08:00-10:00 (2h 00m)", "11:00-12:00 (1h 00m)"]
        )

    def test_empty(self):
        self.assertEqual(round_labels([], 15), [])

    def test_end_of_day(self):
        label = round_labels([Span(1400, 1440)], 10)
        self.assertEqual(label, ["23:20-24:00 (0h 40m)"])


class BadInputTests(unittest.TestCase):
    def test_bad_steps(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(60, 120)], step)

    def test_bad_step_with_no_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_collapsed_span(self):
        with self.assertRaises(ValueError):
            round_span(Span(61, 66), 15)
